{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Sound Baths & Immersive Sessions</title>
  <meta name="description" content="Sensory, premium sound bath events and private 1:1 sessions in {{CITY}}, {{STATE}}. Restore, release, and realign with immersive sound." />
  <link rel="stylesheet" href="assets/css/styles.css" />
  <script defer src="assets/js/main.js"></script>
</head>
<body>
  <div class="site-bg">
    <svg class="bg-pattern" aria-hidden="true"><use href="assets/img/pattern.svg#pattern" /></svg>
  </div>

  <header class="topbar glass">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="/events.html">Upcoming</a>
        <a href="/private-sessions.html">Private</a>
        <a href="/pricing.html">Prices</a>
        <a href="/about.html">Our Story</a>
        <a href="/faq.html">FAQ</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1 class="title">A guided sound bath for deep, sensory restoration</h1>
          <p class="lead">Join a premium immersion led by {{FACILITATOR_NAME}} — vibrating soundscapes of crystal bowls, chimes, and a gentle monochord to help you release tension and re-tune your nervous system.</p>
          <ul class="meta">
            <li><strong>Next event:</strong> {{NEXT_EVENT_DATE}}</li>
            <li><strong>Location:</strong> {{VENUE_NAME}}, {{CITY}}, {{STATE}}</li>
          </ul>
          <div class="hero-cta">
            <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <button id="ripplePreview" class="secondary">Preview the Flow</button>
          </div>
        </div>
        <div class="hero-art glass card">
          <div class="ripple-visual" id="rippleCanvas" aria-hidden="true">
            <svg viewBox="0 0 600 400" preserveAspectRatio="xMidYMid meet">
              <defs>
                <radialGradient id="g1" cx="50%" cy="40%">
                  <stop offset="0%" stop-color="#ffffff" stop-opacity="0.5"/>
                  <stop offset="100%" stop-color="#b8e0ff" stop-opacity="0.06"/>
                </radialGradient>
              </defs>
              <rect width="100%" height="100%" fill="url(#g1)" />
              <g id="ripples" fill="none" stroke="#e6f7ff" stroke-opacity="0.6" stroke-width="2"></g>
            </svg>
          </div>
          <p class="mini">A sensory preview: imagine layered bowls, a single gong swell, and voice-guided breathwork to ease you into sound.</p>
        </div>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social_proof wrap">
      <h2 class="section-title">What participants say</h2>
      <div class="testimonials">
        <blockquote class="glass">"An exquisite, restful evening. I slept better than I have in months." — Ana R., regular attendee</blockquote>
        <blockquote class="glass">"The blend of tuning forks and gong made a subtle, powerful shift." — Marcus P., therapist</blockquote>
        <blockquote class="glass">"VIP-style facilitation — felt held and cared for every minute." — S. Kline</blockquote>
      </div>
    </section>

    <!-- BENEFITS -->
    <section class="benefits wrap">
      <h2 class="section-title">Why a sound bath helps</h2>
      <div class="grid">
        <article class="card glass">
          <h3>Deep relaxation</h3>
          <p>Resonant harmonic tones invite the nervous system to down-regulate — lowering stress hormones and promoting restorative sleep cycles.</p>
        </article>
        <article class="card glass">
          <h3>Embodied presence</h3>
          <p>Guided breathwork and sustained vibrations help anchor attention in the body, making the experience somatic, not merely intellectual.</p>
        </article>
        <article class="card glass">
          <h3>Vibrational clarity</h3>
          <p>Precise instruments (crystal bowls, chimes, and tuning forks) are tuned to support clarity, balance, and a sense of renewed focus.</p>
        </article>
      </div>
    </section>

    <!-- PROCESS (FLOW) -->
    <section class="process wrap">
      <h2 class="section-title">What to expect — session flow</h2>
      <ol class="flow glass">
        <li><strong>Arrival & settling (10m)</strong> — soft tea, lay down on your mat, eye-mask offered.</li>
        <li><strong>Grounding (10m)</strong> — gentle breath cues, intention setting led by the facilitator.</li>
        <li><strong>Main immersion (40–50m)</strong> — waves of sound from crystal bowls, chimes, and a singular gong bloom; layered textures to support release.</li>
        <li><strong>Transition back (10m)</strong> — grounding tones, silence, and a soft vocal prompt to return gently.</li>
        <li><strong>Closing & integration (5–10m)</strong> — brief reflection, sharing optional, next steps for home practice.</li>
      </ol>

      <div class="what-to-bring glass">
        <h3>What to bring</h3>
        <ul>
          <li>Comfortable layers, a yoga mat, bolster or cushion, eye-mask or scarf.</li>
          <li>A light blanket for warmth — we keep the room cool for comfort.</li>
          <li>Optional journal for insights afterward.</li>
        </ul>
      </div>

      <div class="disclaimer glass">
        <h3>Contraindications</h3>
        <p>Sound baths are generally safe, but not recommended during the first trimester of pregnancy, after recent head injury, or directly after surgery without medical clearance. If you have epilepsy, severe auditory sensitivities, or implanted medical devices, consult your clinician before attending. Contact us at {{EMAIL}} with any questions.</p>
      </div>
    </section>

    <!-- LEAD MAGNET -->
    <section class="lead_magnet wrap">
      <div class="glass promo">
        <h2>Free guide: Preparing for your first sound bath</h2>
        <p>Sign up to receive a practical pre-session checklist and a short evening practice to support integration afterwards. Perfect for first-timers and existing practitioners alike.</p>
        <form id="leadForm" class="lead-form">
          <label class="visually-hidden" for="email">Email</label>
          <input id="email" name="email" type="email" placeholder="you@email.com" required />
          <button type="submit" class="primary small">Get the guide</button>
        </form>
        <p class="fineprint">We respect your privacy. Your info will never be shared.</p>
      </div>
    </section>

    <!-- CTA BOTTOM -->
    <section class="cta wrap">
      <div class="glass cta-card">
        <h2>Book a VIP Day or a private session</h2>
        <p>Premium, bespoke sound immersion experiences for individuals or small groups. Ideal for corporate wellness, couples, and 1:1 transformational work.</p>
        <div class="cta-actions">
          <a class="primary" href="/book.html">Book an appointment</a>
          <a class="secondary" href="/private-sessions.html">Learn about private options</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer glass">
    <div class="wrap">
      <div class="foot-col">
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{VENUE_NAME}} • {{CITY}}, {{STATE}}<br /><a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></address>
      </div>
      <div class="foot-col">
        <nav>
          <a href="/events.html">Next events</a>
          <a href="/about.html">Team</a>
          <a href="/contact.html">Contact</a>
        </nav>
      </div>
      <div class="foot-col small">© <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved.</div>
    </div>
  </footer>

</body>
</html>"} 
