{"path":"assets/css/styles.css","content":"/* Glass-morphism sound bath theme */
:root{
  --bg:#071422;
  --card:#ffffff22;
  --glass-border:#ffffff33;
  --accent:#7bd4ff;
  --accent-2:#b9fff6;
  --text:#e6faff;
  --muted:#a9d6e7;
  --radius:14px;
  --fw-regular:500;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:linear-gradient(180deg,#04121a 0%, #082033 60%); color:var(--text); -webkit-font-smoothing:antialiased}
.site-bg{position:fixed;inset:0;z-index:-2;opacity:0.9}
.bg-pattern{position:fixed;inset:0;width:100%;height:100%;opacity:0.35}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.topbar{backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); border-bottom:1px solid var(--glass-border); position:sticky;top:0;z-index:40}
.topbar .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{color:var(--text);font-weight:700;text-decoration:none;font-size:1.05rem}
.nav a{color:var(--muted);margin-left:18px;text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#04202a;font-weight:700}
.hero{padding:48px 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:stretch}
.hero-copy .title{font-size:clamp(1.6rem,3.6vw,2.4rem);margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 16px}
.meta{display:flex;gap:14px;list-style:none;padding:0;margin:0 0 20px}
.meta li{color:var(--muted);font-size:0.95rem}
.hero-cta{display:flex;gap:12px}
.primary{background:linear-gradient(90deg,var(--accent),#9be9ff);color:#04202a;padding:12px 18px;border-radius:10px;text-decoration:none;font-weight:700}
.secondary{background:transparent;border:1px solid var(--glass-border);color:var(--muted);padding:10px 14px;border-radius:10px}
.hero-art{padding:18px;display:flex;flex-direction:column;gap:12px;min-height:240px}
.card{box-shadow:0 6px 24px rgba(3,19,26,0.45)}
.ripple-visual{height:180px;border-radius:12px;overflow:hidden}
.mini{color:var(--muted);font-size:0.95rem;margin:0}
.section-title{font-size:1.15rem;margin:10px 0 16px}
.social_proof .testimonials{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
blockquote{margin:0;padding:16px;border-radius:12px;color:var(--text);font-style:normal}
.benefits .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.card h3{margin:0 0 8px}
.process .flow{list-style:none;padding:18px;border-radius:12px}
.process .flow li{padding:10px 0;border-bottom:1px dashed var(--glass-border);color:var(--muted)}
.what-to-bring,.disclaimer{margin-top:16px;padding:12px}
.lead_magnet .promo{display:flex;flex-direction:column;gap:12px;align-items:flex-start}
.lead-form{display:flex;gap:10px;width:100%}
.lead-form input{flex:1;padding:12px;border-radius:10px;border:1px solid var(--glass-border);background:transparent;color:var(--text)}
.lead-form button{padding:10px 14px;border-radius:10px}
.fineprint{font-size:0.82rem;color:var(--muted)}
.cta-card{text-align:center;padding:22px}
.cta-actions{display:flex;gap:12px;justify-content:center;margin-top:12px}
.site-footer{margin-top:36px;padding:20px;border-top:1px solid var(--glass-border)}
.site-footer .wrap{display:flex;gap:12px;align-items:center}
.foot-col{flex:1}
.small{font-size:0.85rem;color:var(--muted)}
.visually-hidden{position:absolute;height:1px;width:1px;overflow:hidden;clip:rect(1px,1px,1px,1px)}
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr;}
  .social_proof .testimonials{grid-template-columns:1fr}
  .benefits .grid{grid-template-columns:1fr}
}
/* subtle animations */
#ripples circle{stroke-opacity:0.45;transform-origin:center}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Year in footer
  var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

  // Ripple preview generator in hero
  var rippleBtn=document.getElementById('ripplePreview');
  var ripplesGroup=document.querySelector('#ripples');
  function makeRipple(x,y,size,delay){
    var svgns='http://www.w3.org/2000/svg';
    var c=document.createElementNS(svgns,'circle');
    c.setAttribute('cx',x);
    c.setAttribute('cy',y);
    c.setAttribute('r',size);
    c.setAttribute('stroke','#dff6ff');
    c.setAttribute('stroke-width',2);
    c.setAttribute('fill','none');
    c.style.opacity='0';
    ripplesGroup.appendChild(c);
    // animate
    setTimeout(function(){
      c.animate([
        {transform:'scale(0.1)',opacity:0.9},
        {transform:'scale(1.6)',opacity:0}
      ],{duration:1600,easing:'cubic-bezier(.2,.8,.2,1)'}).onfinish=function(){c.remove()}
    },delay||0);
  }
  if(rippleBtn) rippleBtn.addEventListener('click',function(){
    // create layered ripple pattern across the svg
    var vb=document.querySelector('svg').viewBox.baseVal;
    var w=vb.width||600,h=vb.height||400;
    for(var i=0;i<8;i++){
      var nx=240 + Math.sin(i*1.2)*120 + (Math.random()-0.5)*40;
      var ny=120 + Math.cos(i*0.9)*60 + (Math.random()-0.5)*30;
      makeRipple(nx,ny,10 + i*8, i*120);
    }
  });

  // Lead magnet form
  var leadForm=document.getElementById('leadForm');
  if(leadForm) leadForm.addEventListener('submit',function(e){
    e.preventDefault();
    var email=leadForm.querySelector('input[name=email]').value.trim();
    if(!email || !/.+@.+\..+/.test(email)){
      alert('Please enter a valid email.'); return;
    }
    // Simulate async submit
    leadForm.querySelector('button').disabled=true;
    leadForm.querySelector('button').textContent='Sending...';
    setTimeout(function(){
      leadForm.innerHTML='<p class="fineprint">Thanks — check your inbox for the guide. We look forward to seeing you at a session.</p>';
    },900);
  });

  // Simple external CTA handler to respect placeholder URLs
  var ctas=document.querySelectorAll('a.primary');
  ctas.forEach(function(a){
    a.addEventListener('click',function(e){
      // allow normal behavior; this handler can be extended for analytics
    })
  });

});
"} 
